function Profile({ user }) {
  if (!user) {
    return <p>Loading…</p>;
  }
  const [tab, setTab] = useState('info');
  return <Tabs active={tab} onChange={setTab} user={user} />;
}

function Search({ query }) {
  const [results, setResults] = useState([]);
  useEffect(() => {
    fetch(`/api?q=${query}`)
      .then((r) => r.json())
      .then(setResults);
  }, [query]);
  return <List items={results} />;
}

